### C++

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct SegTree {
    vector<long long> mx, lazy;
    int n;

    SegTree(const vector<long long>& arr, int n) : n(n) {
        mx.assign(4 * n + 5, 0);
        lazy.assign(4 * n + 5, 0);
        build(1, 1, n, arr);
    }

    void build(int node, int l, int r, const vector<long long>& arr) {
        if (l == r) {
            mx[node] = arr[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(node << 1, l, mid, arr);
        build(node << 1 | 1, mid + 1, r, arr);
        mx[node] = max(mx[node << 1], mx[node << 1 | 1]);
    }

    void push(int node) {
        if (lazy[node]) {
            long long tag = lazy[node];
            mx[node << 1] += tag;
            mx[node << 1 | 1] += tag;
            lazy[node << 1] += tag;
            lazy[node << 1 | 1] += tag;
            lazy[node] = 0;
        }
    }

    void rangeAdd(int node, int l, int r, int ql, int qr, long long val) {
        if (ql <= l && r <= qr) {
            mx[node] += val;
            lazy[node] += val;
            return;
        }
        push(node);
        int mid = (l + r) >> 1;
        if (ql <= mid) rangeAdd(node << 1, l, mid, ql, qr, val);
        if (qr > mid) rangeAdd(node << 1 | 1, mid + 1, r, ql, qr, val);
        mx[node] = max(mx[node << 1], mx[node << 1 | 1]);
    }

    long long queryMax() {
        return mx[1];
    }
};

long long solveCase(int n, const vector<long long>& a,
                    const vector<int>& p, const vector<int>& q) {
    vector<long long> s(n + 1);
    vector<int> pos(n + 1);
    for (int i = 1; i <= n; i++) {
        s[i] = a[p[i]];
        pos[p[i]] = i;
    }

    vector<long long> pre(n + 1);
    for (int i = 1; i <= n; i++) {
        pre[i] = pre[i - 1] + s[i];
    }

    SegTree seg(pre, n);
    long long ans = max(0LL, seg.queryMax());

    for (int i = 1; i <= n; i++) {
        int x = q[i];
        int idx = pos[x];
        seg.rangeAdd(1, 1, n, idx, n, -a[x]);
        ans = max(ans, seg.queryMax());
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<long long> a(n + 1);
        vector<int> p(n + 1), q(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];
        for (int i = 1; i <= n; i++) cin >> p[i];
        for (int i = 1; i <= n; i++) cin >> q[i];
        cout << solveCase(n, a, p, q) << '\n';
    }
    return 0;
}
